import math

def factorize(n):
    factors = set()
    d = 2
    temp = n
    while d * d <= temp:
        if temp % d == 0:
            factors.add(d)
            while temp % d == 0:
                temp //= d
        d += 1
    if temp > 1:
        factors.add(temp)
    return factors

def check_n(n):
    # D(n) = n^3 + 4n^2 + 6n + 4
    D_n = n**3 + 4*n**2 + 6*n + 4

    # Condition 1: D(n) must divide 20^(n+1).
    # Since 20^(n+1) = 2^(2n+2) * 5^(n+1), all prime factors of D(n) must be 2 or 5.

    prime_factors = factorize(D_n)

    is_valid_divisor = all(p == 2 or p == 5 for p in prime_factors)

    # If the prime factors are only 2 and 5, the divisibility condition 
    # 20^(n+1) % D(n) == 0 must hold.

    if is_valid_divisor:
        # Check the actual divisibility
        numerator = 20**(n + 1)
        if numerator % D_n == 0:
            return n, "Solution", prime_factors
        else:
            return n, "Not Solution (Divisibility fails)", prime_factors
    else:
        return n, "Not Solution (Factor constraint fails)", prime_factors

N_max = 10
results = {}
for n in range(N_max + 1):
