def is_power_of_2_and_5(N):
    # Checks if N = 2^c * 5^d for non-negative integers c, d
    if N <= 0:
        return False

    temp_N = N
    # Divide out all factors of 2
    while temp_N % 2 == 0:
        temp_N //= 2

    # Divide out all factors of 5
    while temp_N % 5 == 0:
        temp_N //= 5

    # If the remainder is 1, N only contained factors 2 and 5
    return temp_N == 1

