def find_candidates(max_a=12, max_b=5):
    results = set()
    for a in range(max_a + 1):
        for b in range(max_b + 1):
            n_plus_2 = (2**a) * (5**b)
            if n_plus_2 > 1000:
                n = n_plus_2 - 2
                Q_n = n*n + 2*n + 2
